        hourBranch: planEntry.hourBranch,
        label: `${candidateSolarDate} \xB7 ${hourLabelForTimeIndex(planEntry.timeIndex)}`,
        clockWindow: clockWindowForPlan(sourceSolarDate, planEntry),
        syntheticLocalTime,
