function stableFingerprint(value) {
  let hash2 = 2166136261;
  for (const char of value) {
    hash2 ^= char.codePointAt(0) ?? 0;
    hash2 = Math.imul(hash2, 16777619);
  }
  return `fp-${(hash2 >>> 0).toString(16)}`;
}
function getZiweiCandidateFingerprint(candidates) {
  const value = candidates.map((candidate) => [candidate.key, candidate.sourceSolarDate, candidate.chart?.solarDate].join(":")).sort().join("|");
  return stableFingerprint(value);
}

