    hourResolutionMode: conversation.hourResolutionMode,
    inferenceStatus: remainingActive <= 1 ? "awaiting_lock" : "hypotheses",
    inferenceRound: conversation.inferenceRound,
    hourCandidates: candidates,
    lifeHypotheses: conversation.lifeHypotheses,
    calibrationLedger: [...conversation.calibrationLedger, ledgerEntry],
    calibrationOperations: conversation.calibrationOperations ?? [],
    inferenceFindings: conversation.inferenceFindings ?? [],
    inferenceCalls: conversation.inferenceCalls ?? [],
    lockedHour: conversation.lockedHour,
    ledgerRevision: nextRevision,
    candidateFingerprint: fingerprint,
    inferenceRevision: conversation.inferenceRevision ?? 0,
    generationRequestSeq: conversation.generationRequestSeq ?? 0,
    activeQuestionSeedId: void 0,
    adjudicationStatus,
    requiresReaudit: rolledBack
