const data = JSON.parse(document.getElementById('stars-data').textContent);
const grid = document.getElementById('board');
function render(idx){
  const cand = data.candidates[idx];
  document.querySelectorAll('.cand').forEach((el, i) => el.classList.toggle('active', i === idx));
  const src = data.source;
  document.getElementById('head').innerHTML =
    '<span>' + esc(src.gender) + ' \xB7 ' + esc(src.solarDate) + (src.time ? ' ' + esc(src.time) : '\uFF08\u65F6\u8FB0\u672A\u77E5\uFF09') + '</span>' +
    '<span>' + (src.trueSolarApplied ? '\u771F\u592A\u9633\u65F6\u5DF2\u6821\u51C6\uFF08+' + src.correctionMinutes + ' \u5206\u949F\uFF09' : '\u672A\u6821\u51C6\uFF08--no-true-solar\uFF09') + '</span>' +
    '<span>' + esc(cand.label) + (cand.clockWindow ? ' \xB7 \u949F\u8868\u7A97\u53E3 ' + esc(cand.clockWindow) : '') + '</span>' +
    '<span>' + esc(cand.status === 'locked' ? '\u5DF2\u9501\u5B9A' : cand.status === 'eliminated' ? '\u5DF2\u6392\u9664' : '\u6D3B\u8DC3') + '</span>';
  const cells = {};
  for (const p of cand.chart.palaces) {
    const pos = BRANCH_POS[BRANCH_INDEX[p.earthlyBranch]] || [2, 2];
    cells[pos[0] + '-' + pos[1]] = p;
  }
  let html = '';
  for (const branch of BRANCH_ORDER) {
    const pos = BRANCH_POS[branch];
    const p = cells[pos[0] + '-' + pos[1]];
    if (!p) { html += '<div class="cell"></div>'; continue; }
    const stars = p.majorStars.concat(p.borrowedMajorStars).map(s => {
      const mut = s.mutagen ? ' <span class="mut">\u5316' + esc(s.mutagen) + '</span>' : '';
      const bri = s.brightness ? ' (' + esc(s.brightness) + ')' : '';
      return '<span class="star">' + esc(s.name) + mut + bri + '</span>';
    }).join('');
    const marks = [];
    if (p.isSoulPalace) marks.push('\u547D\u5BAB');
    if (p.isBodyPalace) marks.push('\u8EAB\u5BAB');
    if (p.isEmptyMajor) marks.push('\u7A7A\u5BAB\u501F\u661F');
    const daxian = p.decadal ? '\u5927\u9650 ' + p.decadal.startAge + '-' + p.decadal.endAge + ' \u5C81' : '';
    html += '<div class="cell' + (p.isSoulPalace ? ' soul' : '') + '">' +
      '<div class="head"><span class="stem">' + esc(p.heavenlyStem) + esc(p.earthlyBranch) + '</span><span>' + esc(p.palace) + '</span></div>' +
      '<div class="marks">' + marks.join(' \xB7 ') + '</div>' +
      '<div class="stars">' + (stars || '<span class="dim">\u7A7A</span>') + '</div>' +
      (daxian ? '<div class="daxian">' + esc(daxian) + '</div>' : '') +
      '</div>';
  }
  grid.innerHTML = html;
}
